# FILE: Chart.yaml
apiVersion: v2
name: postgres
description: Helm chart deploying PostgreSQL for non-production with StatefulSet, headless Service, PVC, Secret for credentials, and an init Job to create the application database.
type: application
version: 0.1.0
appVersion: "16.3"
kubeVersion: ">=1.21.0-0"
---
# FILE: values.yaml
image:
  repository: postgres
  tag: "16.3"
  pullPolicy: IfNotPresent

imagePullSecrets: []
# - name: my-registry-secret

replicaCount: 1

service:
  port: 5432
  annotations: {}

persistence:
  enabled: true
  accessModes:
    - ReadWriteOnce
  size: 10Gi
  storageClass: "" # if empty, default storage class is used

