          {{- end }}
          env:
            - name: PGHOST
              value: {{ printf "%s-postgres" .Release.Name | trunc 63 | trimSuffix "-" }}
            - name: PGPORT
              value: "{{ .Values.service.port }}"
            - name: POSTGRES_USER
              valueFrom:
                secretKeyRef:
                  name: {{ default (printf "%s-postgres-credentials" .Release.Name | trunc 63 | trimSuffix "-") .Values.credentials.existingSecret }}
                  key: postgres-username
            - name: POSTGRES_PASSWORD
              valueFrom:
                secretKeyRef:
                  name: {{ default (printf "%s-postgres-credentials" .Release.Name | trunc 63 | trimSuffix "-") .Values.credentials.existingSecret }}
                  key: postgres-password
            - name: APP_USER
              valueFrom:
                secretKeyRef:
                  name: {{ default (printf "%s-postgres-credentials" .Release.Name | trunc 63 | trimSuffix "-") .Values.credentials.existingSecret }}
                  key: app-username
            - name: APP_PASSWORD
              valueFrom:
                secretKeyRef:
                  name: {{ default (printf "%s-postgres-credentials" .Release.Name | trunc 63 | trimSuffix "-") .Values.credentials.existingSecret }}
                  key: app-password
            - name: APP_DB
              value: {{ .Values.appDatabase.name | quote }}
          command:
            - /bin/sh
            - -c
            - |
              set -euo pipefail

              echo "Waiting for PostgreSQL to be ready at ${PGHOST}:${PGPORT}..."
              for i in $(seq 1 60); do
                if PGPASSWORD="${POSTGRES_PASSWORD}" pg_isready -h "${PGHOST}" -p "${PGPORT}" -U "${POSTGRES_USER}" >/dev/null 2>&1; then
                  echo "PostgreSQL is ready."
                  break
                fi
                sleep 5
              done

              if ! PGPASSWORD="${POSTGRES_PASSWORD}" pg_isready -h "${PGHOST}" -p "${PGPORT}" -U "${POSTGRES_USER}" >/dev/null 2>&1; then
                echo "PostgreSQL not ready after waiting, exiting."
                exit 1
              fi

              PSQL="psql --no-password -h ${PGHOST} -p ${PGPORT} -U ${POSTGRES_USER} -v ON_ERROR_STOP=1"

              # Create role and database idempotently using safe quoting
              ${PSQL} -v app_user="${APP_USER}" -v app_password="${APP_PASSWORD}" -v app_db="${APP_DB}" <<'SQL'
              DO
              $do$
              BEGIN
